constraints:
1 ≤ N ≤ 5*10^{5}
1 ≤ arr[i] ≤ 10^{18}

expected time complexity: O(NLogN).
expected auxiliary space: O(N).

standard_solution_code:
class Solution:

	def merge(self, start, mid, end, arr):
		(len1, len2) = (mid - start + 1, end - mid)
		arr1 = [arr[ind] for ind in range(start, mid + 1)]
		arr2 = [arr[ind] for ind in range(mid + 1, end + 1)]
		(i, j, k) = (0, 0, start)
		count = 0
		while i < len1 and j < len2:
			if arr1[i] <= arr2[j]:
				arr[k] = arr1[i]
				i += 1
			else:
				arr[k] = arr2[j]
				count += len1 - i
				j += 1
			k += 1
		while i < len1:
			arr[k] = arr1[i]
			i += 1
			k += 1
		while j < len2:
			arr[k] = arr2[j]
			j += 1
			k += 1
		return count

	def mergeSort(self, start, end, arr):
		count = 0
		if start < end:
			mid = start + (end - start) // 2
			l = self.mergeSort(start, mid, arr)
			r = self.mergeSort(mid + 1, end, arr)
			count = self.merge(start, mid, end, arr) + l + r
		return count

	def inversionCount(self, nums, n):
		return self.mergeSort(0, n - 1, nums)
